pub fn match_types(
    mut self,
    types: impl IntoIterator<Item = impl Into<teaql_core::Value>>,
) -> Self {
    self.query = self.query.and_filter(Expr::in_list(TYPE_FIELD, types.into_iter().map(Into::into)));
    self
}

